ragraph {\"className\":\"ts-corp__eyebrow\"} -->\n<p class=\"ts-corp__eyebrow\">Corporate quote</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Let’s Plan Your Team’s Massage Event</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p>Share a few details about your organization, preferred date, venue and the time you have available. I will follow up to talk through the format and send you a quote.</p>\n<!-- /wp:paragraph -->\n<!-- wp:buttons {\"className\":\"ts-corp__actions\"} -->\n<div class=\"wp-block-buttons ts-corp__actions\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"mailto:butsabad@gmail.com?subject=Corporate%20massage%20quote%20request&amp;body=Hi%20Butsaba%2C%0A%0AI%20would%20like%20a%20quote%20for%20a%20corporate%20massage%20event.%0A%0AOrganization%3A%0AContact%20name%20and%20phone%3A%0AEvent%20date%20%28or%20%22flexible%22%29%3A%0AEvent%20location%20%28venue%20and%20city%29%3A%0AApproximate%20number%20of%20participants%3A%0AService%20hours%20requested%20%28for%20example%203%20or%205%29%3A%0AMassage%20type%20%28chair%20massage%2C%20table%20massage%2C%20or%20not%20sure%20yet%29%3A%0AAnything%20else%20I%20should%20know%3A%0A\">Request a Corporate Massage Quote</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n<!-- wp:paragraph {\"className\":\"ts-corp__fine\"} -->\n<p class=\"ts-corp__fine\">The button opens an email to <a href=\"mailto:butsabad@gmail.com\">butsabad@gmail.com</a> with prompts for the date, venue, group size, hours and massage type, so you can fill it in and send. Planning a series of staff events? Mention the schedule in your inquiry.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n",
